PHP_REMOTE_SCAN = "<?php
declare(strict_types=1);

$webroot = getenv('FP_WEBROOT');

function out(array $payload): void
{
    echo json_encode(
        $payload,
        JSON_UNESCAPED_UNICODE
        | JSON_UNESCAPED_SLASHES
        | JSON_INVALID_UTF8_SUBSTITUTE
    );
    echo PHP_EOL;
}

if (!is_string($webroot) || $webroot === '' || !is_dir($webroot)) {
    out(['ok' => false, 'error' => 'FP_WEBROOT invalid']);
    exit(2);
}

$webroot = rtrim($webroot, '/');

$tokens = [
    'sitemap.xml',
    'sitemap',
    'urlset',
    'lastmod',
    'changefreq',
    'priority',
    'file_put_contents',
    'fopen(',
    'simplexmlelement',
    'domdocument',
    'goods',
    'visible',
    'alias'
];

$allowedExtensions = [
    'php' => true,
    'xml' => true,
    'conf' => true,
    'txt' => true,
    'htaccess' => true
];

$excludedDirs = [
    'userfiles' => true,
    'cache' => true,
    'vendor' => true,
    'node_modules' => true
];

$hits = [];
$maxHits = 1000;

$directory = new RecursiveDirectoryIterator(
    $webroot,
    FilesystemIterator::SKIP_DOTS
);

$filter = new RecursiveCallbackFilterIterator(
    $directory,
    static function (SplFileInfo $current) use ($excludedDirs): bool {
        if ($current->isDir()) {
            return !isset($excludedDirs[$current->getFilename()]);
        }

        return true;
    }
);

$iterator = new RecursiveIteratorIterator($filter);

foreach ($iterator as $fileInfo) {
    if (count($hits) >= $maxHits) {
        break;
    }

    if (!$fileInfo->isFile()) {
        continue;
    }

    $filename = $fileInfo->getFilename();
    $extension = strtolower(pathinfo($filename, PATHINFO_EXTENSION));

    if ($filename === '.htaccess') {
        $extension = 'htaccess';
    }

    if (!isset($allowedExtensions[$extension])) {
        continue;
    }

    $path = $fileInfo->getPathname();
    $contents = @file_get_contents($path);

    if (!is_string($contents)) {
        continue;
    }

    $lines = preg_split('/\R/u', $contents);

    if (!is_array($lines)) {
        continue;
    }

    foreach ($lines as $index => $line) {
        $lower = strtolower((string)$line);
        $matched = false;

        foreach ($tokens as $token) {
            if (strpos($lower, strtolower($token)) !== false) {
                $matched = true;
                break;
            }
        }

        if (!$matched) {
            continue;
        }

        $hits[] = [
            'file' => $path,
            'line' => $index + 1,
            'text' => trim((string)$line)
        ];

        if (count($hits) >= $maxHits) {
            break 2;
        }
    }
}

$sitemapPath = $webroot . '/sitemap.xml';

out([
    'ok' => true,
    'php_version' => PHP_VERSION,
    'sitemap_file' => [
        'path' => $sitemapPath,
        'exists' => is_file($sitemapPath),
        'bytes' => is_file($sitemapPath) ? filesize($sitemapPath) : null,
        'mtime' => is_file($sitemapPath) ? filemtime($sitemapPath) : null,
        'sha256' => is_file($sitemapPath)
            ? hash_file('sha256', $sitemapPath)
            : null
    ],
    'hits' => $hits
]);
"
